package game

import (
	"testing"
)

// duration_creature_cast_upkeep_end_test.go — #6229. CR 611.2a: "A
// continuous effect generated by the resolution of a spell or ability
// lasts as long as stated by the spell or ability creating it."
//
//   - "until a player casts a creature spell" (Soul Sculptor) ends on
//     the event, whoever casts it, and on nothing else;
//   - "until the end of your next upkeep" (Halfdane) lasts through the
//     named player's next upkeep step and ends as it ends.

func liveOfKind(g *Game, k DurationKind) int {
	n := 0
	g.ReadSnapshot(func() {
		for _, e := range g.ScopedEffects {
			if e.Duration.Kind == k {
				n++
			}
		}
	})
	return n
}

// Soul Sculptor: turns pass and a noncreature spell is cast, and the
// effect stays; an opponent's creature spell ends it, and it survives a
// restore while it waits.
func TestUntilACreatureSpellIsCastEndsOnAnyCreatureSpell(t *testing.T) {
	g := newActiveGame(t)
	bear := pushScopedTestCreature(g, g.Seats[1].ID, 2, 2)
	d := UntilACreatureSpellIsCastDuration()
	if !d.Known() {
		t.Fatalf("duration %+v is not known: %s", d, d.Problem())
	}
	registerDurationMarker(g, bear, d, "Soul Sculptor")
	advanceOneTurn(t, g)
	advanceOneTurn(t, g)
	if liveOfKind(g, UntilACreatureSpellIsCast) != 1 {
		t.Fatal("a turn boundary ended the effect")
	}
	g = restoreStrictForTest(t, g)
	me := g.Seats[0]

	sorcery := spellInHand(t, g, me, "Divination", "Sorcery", "")
	if err := g.CastSpell(me.ID, sorcery, CastSpellParams{FromZone: "hand"}); err != nil {
		t.Fatalf("cast sorcery: %v", err)
	}
	if liveOfKind(g, UntilACreatureSpellIsCast) != 1 {
		t.Fatal("a noncreature spell ended the effect")
	}
	resolveWholeStackForTest(t, g)
	creature := spellInHand(t, g, me, "Grizzly Bears", "Creature — Bear", "")
	if err := g.CastSpell(me.ID, creature, CastSpellParams{FromZone: "hand"}); err != nil {
		t.Fatalf("cast creature: %v", err)
	}
	if liveOfKind(g, UntilACreatureSpellIsCast) != 0 {
		t.Error("a creature spell did not end the effect")
	}
}

// Halfdane: made in its player's upkeep, the effect lasts through every
// other seat's turn and through its player's next upkeep, and ends as
// that upkeep ends.
func TestUntilEndOfYourNextUpkeepLastsThroughThatUpkeep(t *testing.T) {
	g := newFourPlayerActiveGame(t)
	if g.Turn.Step != StepUpkeep || g.Turn.ActiveSeat != 0 {
		t.Fatalf("the table starts at %v of seat %d, want seat 0's upkeep", g.Turn.Step, g.Turn.ActiveSeat)
	}
	bear := pushScopedTestCreature(g, g.Seats[0].ID, 2, 2)
	var d Duration
	g.WithWriteLock(func() { d = g.UntilEndOfYourNextUpkeepDuration(g.Seats[0].ID) })
	if !d.Known() {
		t.Fatalf("duration %+v is not known: %s", d, d.Problem())
	}
	registerDurationMarker(g, bear, d, "Halfdane")

	advanceIntoStep(t, g, StepDraw)
	if liveOfKind(g, UntilEndOfYourNextUpkeep) != 1 {
		t.Fatal("the effect ended with the upkeep it was made in")
	}
	for seat := 1; seat <= 3; seat++ {
		advanceToStepOfSeat(t, g, seat, StepUpkeep)
		if liveOfKind(g, UntilEndOfYourNextUpkeep) != 1 {
			t.Fatalf("the effect ended during seat %d's turn", seat)
		}
	}
	advanceToStepOfSeat(t, g, 0, StepUpkeep)
	if liveOfKind(g, UntilEndOfYourNextUpkeep) != 1 {
		t.Fatal("the effect ended as its player's next upkeep began, not as it ended")
	}
	advanceIntoStep(t, g, StepDraw)
	if liveOfKind(g, UntilEndOfYourNextUpkeep) != 0 {
		t.Error("the effect outlived the end of its player's next upkeep")
	}
}

// The two kinds are appended, so every persisted int keeps its meaning:
// 15 and 16, and the last known.
func TestNewDurationKindsKeepTheirPersistedInts(t *testing.T) {
	if int(UntilACreatureSpellIsCast) != 15 || int(UntilEndOfYourNextUpkeep) != 16 || (UntilEndOfYourNextUpkeep + 1).Known() {
		t.Errorf("persisted ints %d, %d; want 15, 16 and the last known kind", UntilACreatureSpellIsCast, UntilEndOfYourNextUpkeep)
	}
}

func TestNewDurationKindsHaveWords(t *testing.T) {
	for _, k := range []DurationKind{UntilACreatureSpellIsCast, UntilEndOfYourNextUpkeep} {
		if !k.Known() || k.String() == "unknown duration" {
			t.Errorf("kind %d: known=%v string=%q", k, k.Known(), k.String())
		}
	}
	if p := (Duration{Kind: UntilACreatureSpellIsCast, Ended: true}).Problem(); p != "" {
		t.Errorf("an ended creature-cast duration was refused: %s", p)
	}
}
